@pytest.mark.parametrize("yaw,gap,seed,t", GRID) def test_frozen_gap_on_the_label_body_distance_chose_is_the_distance(yaw, gap, seed, t): """文档工作流：body_distance 选标签 → frozen_ee_sign 定朝向 → margin_gap_from_frozen_cover。分离的一对，冻结间隙必须是 +d （修前 96 个 EE 位形里 19 个给 −d：分离判成闭合），δ = 0.5d 时冻结间隙 0.5d 且 inflated_membership 答 OUTSIDE。""" A, B = _stack(yaw, gap, seed, t) d, lab = body_distance(A, B) if lab[0] != "EE": pytest.skip(f"nearest label is {lab[0]}, not EE") ea, eb = (lab[1][1], lab[1][2]), (lab[2][1], lab[2][2]) sgn = frozen_ee_sign(A, B, ea, eb) tol = 1e-9 * max(1.0, d) + 4096 * 2.220446049250313e-16 * max(1.0, t) g = margin_gap_from_frozen_cover(A, B, lab, (0.0, 0.0, 0.0), 0.0, ee_sign=sgn) > assert abs(g - d) <= tol, (d, g, sgn) E AssertionError: (0.0009999999999999185, -0.0009999999999999083, -1.0) E assert 0.0019999999999998266 <= 1.000909494701773e-09 E + where 0.0019999999999998266 = abs((-0.0009999999999999083 - 0.0009999999999999185))
